import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';
import '../../core/api_client.dart';

class DeliveryMapPage extends StatefulWidget { const DeliveryMapPage({super.key,required this.api}); final PosApiClient api; @override State<DeliveryMapPage> createState()=>_DeliveryMapPageState(); }
class _DeliveryMapPageState extends State<DeliveryMapPage>{List<dynamic> riders=[];Timer? timer;@override void initState(){super.initState();load();timer=Timer.periodic(const Duration(seconds:15),(_)=>load());}@override void dispose(){timer?.cancel();super.dispose();}Future<void> load()async{try{final r=await widget.api.riderList();if(mounted)setState(()=>riders=r);}catch(_){}}@override Widget build(BuildContext context){final points=<Marker>[];for(final item in riders){final loc=item['location'];final lat=(loc?['latitude'] as num?)?.toDouble();final lon=(loc?['longitude'] as num?)?.toDouble();if(lat!=null&&lon!=null)points.add(Marker(point:LatLng(lat,lon),width:48,height:48,child:Tooltip(message:'${item['username']} • ${item['vehicleNumber']}',child:const Icon(Icons.delivery_dining,size:40))));}final center=points.isNotEmpty?points.first.point:const LatLng(31.4504,73.1385);return Scaffold(appBar:AppBar(title:const Text('Live Rider Map'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),body:Column(children:[Expanded(child:FlutterMap(options:MapOptions(initialCenter:center,initialZoom:13),children:[TileLayer(urlTemplate:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',userAgentPackageName:'com.findupto.pos'),MarkerLayer(markers:points)])),SizedBox(height:150,child:ListView.builder(itemCount:riders.length,itemBuilder:(_,i){final r=Map<String,dynamic>.from(riders[i]);return ListTile(leading:Icon(r['online']==true?Icons.gps_fixed:Icons.gps_off),title:Text('${r['username']}'),subtitle:Text('${r['vehicleType']} ${r['vehicleNumber']} • ${r['online']==true?'Online':'Offline'}'),trailing:Text(r['available']==true?'Available':'Busy'));}))]));}}
